VAL=[(0,10.5915),(50,6.9325),(100,6.0262),(150,5.5833),(200,5.1485),(250,4.8842),(300,4.6929),(350,4.5525),(400,4.4227),(450,4.2986),(500,4.1949),(550,4.1115),(600,4.0391),(650,3.9882),(700,3.9451),(750,3.9056),(800,3.8681),(850,3.8354),(900,3.8078),(950,3.7782),(1000,3.7602),(1050,3.7367),(1100,3.7246),(1150,3.7018),(1200,3.6852),(1250,3.6644),(1300,3.6528),(1350,3.6374),(1400,3.6233),(1450,3.6091),(1500,3.5966),(1550,3.5851),(1600,3.5717),(1650,3.5635),(1700,3.5535),(1750,3.5434),(1800,3.5333),(1850,3.5272),(1900,3.5159),(1950,3.5085),(2000,3.5029),(2050,3.4934),(2100,3.4877),(2150,3.4772),(2200,3.4717),(2250,3.4632),(2300,3.4612),(2350,3.452),(2400,3.4463),(2450,3.4416),(2500,3.4374),(2550,3.4316),(2600,3.4262),(2650,3.4226),(2700,3.4181),(2750,3.4131),(2800,3.4099),(2850,3.4058),(2900,3.4038),(2950,3.4003),(3000,3.3973),(3050,3.394),(3100,3.3917),(3150,3.3894),(3200,3.3877),(3250,3.3862),(3300,3.3847),(3350,3.3824),(3360,3.3823)]
TOK=524288; STEPS=len(TRAIN); WARM,PEAK,FLOOR=150,6e-4,6e-5
def lr_at(s):
    if s<WARM: return PEAK*(s+1)/WARM
    return FLOOR+0.5*(PEAK-FLOOR)*(1+math.cos(math.pi*(s-WARM)/(STEPS-WARM)))
def smooth(x,w=25):
    out=[]
    for i in range(len(x)):
        h=min(w//2,i,len(x)-1-i); out.append(sum(x[i-h:i+h+1])/(2*h+1))   # centred; narrower at the ends
    return out
SM=smooth(TRAIN)
W,H=780,820; L,R,T=70,64,24
P1=(T,300); P2=(350,560); P3=(610,750)
X1=1.8
def sx(s): return L+s*TOK/1e9/X1*(W-L-R)
def sy1(y): return P1[1]-(y-3)/(11-3)*(P1[1]-P1[0])
Z0,Z1=3.3,4.1
def sy2(y): return P2[1]-(y-Z0)/(Z1-Z0)*(P2[1]-P2[0])
def sl(lr): return P2[1]-lr/6.6e-4*(P2[1]-P2[0])
def sy3(g): return P3[1]-(math.log10(g)-math.log10(0.15))/(math.log10(12)-math.log10(0.15))*(P3[1]-P3[0])
def svg(th):
    ink,mut,grid,acc,surf,acc2,faint=th
    o=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}" font-family="Arial,Helvetica,sans-serif" role="img">']
    o.append(f'<rect width="{W}" height="{H}" fill="{surf}"/>')
    o.append(f'<defs><clipPath id="c2"><rect x="{L}" y="{P2[0]}" width="{W-L-R}" height="{P2[1]-P2[0]}"/></clipPath></defs>')
    for y in range(3,12):
        o.append(f'<line x1="{L}" x2="{W-R}" y1="{sy1(y):.1f}" y2="{sy1(y):.1f}" stroke="{grid}" stroke-width="1"/>')
        o.append(f'<text x="{L-8}" y="{sy1(y)+4:.1f}" fill="{mut}" font-size="13" text-anchor="end">{y}</text>')
    for y in (3.3,3.5,3.7,3.9,4.1):
        o.append(f'<line x1="{L}" x2="{W-R}" y1="{sy2(y):.1f}" y2="{sy2(y):.1f}" stroke="{grid}" stroke-width="1"/>')
        o.append(f'<text x="{L-8}" y="{sy2(y)+4:.1f}" fill="{mut}" font-size="13" text-anchor="end">{y:.1f}</text>')
    for lr,lab in ((0,'0'),(2e-4,'2'),(4e-4,'4'),(6e-4,'6')):
        o.append(f'<text x="{W-R+8}" y="{sl(lr)+4:.1f}" fill="{mut}" font-size="13">{lab}</text>')
    for g,lab in ((0.2,'0.2'),(0.5,'0.5'),(1,'1'),(2,'2'),(5,'5'),(10,'10')):
        o.append(f'<line x1="{L}" x2="{W-R}" y1="{sy3(g):.1f}" y2="{sy3(g):.1f}" stroke="{grid}" stroke-width="1"/>')
        o.append(f'<text x="{L-8}" y="{sy3(g)+4:.1f}" fill="{mut}" font-size="13" text-anchor="end">{lab}</text>')
    for k in range(0,8):
        b=k*0.25; x=L+b/X1*(W-L-R)
        for a,c in (P1,P2,P3):
            o.append(f'<line x1="{x:.1f}" x2="{x:.1f}" y1="{a}" y2="{c}" stroke="{grid}" stroke-width="1"/>')
        o.append(f'<text x="{x:.1f}" y="{P3[1]+20}" fill="{mut}" font-size="13" text-anchor="middle">{b:g}</text>')
    o.append(f'<text x="{(L+W-R)/2}" y="{H-24}" fill="{ink}" font-size="14" text-anchor="middle">Training tokens (billions); 3,360 steps of 524,288 tokens</text>')
    o.append(f'<text transform="translate(20,{sum(P1)/2}) rotate(-90)" fill="{ink}" font-size="14" text-anchor="middle">Loss (nats per token)</text>')
    o.append(f'<text transform="translate(20,{sum(P2)/2}) rotate(-90)" fill="{ink}" font-size="14" text-anchor="middle">Loss, zoomed</text>')
    o.append(f'<text transform="translate({W-14},{sum(P2)/2}) rotate(90)" fill="{ink}" font-size="14" text-anchor="middle">Learning rate (×10⁻⁴)</text>')
    o.append(f'<text transform="translate(20,{sum(P3)/2}) rotate(-90)" fill="{ink}" font-size="14" text-anchor="middle">Gradient norm</text>')
    # panel 1
    u=7.59
    o.append(f'<line x1="{L}" x2="{W-R}" y1="{sy1(u):.1f}" y2="{sy1(u):.1f}" stroke="{mut}" stroke-width="1.5" stroke-dasharray="7 5"/>')
    o.append(f'<text x="{W-R-6}" y="{sy1(u)-7:.1f}" fill="{ink}" font-size="13" text-anchor="end">token frequencies alone (unigram): 7.59</text>')
    o.append(f'<polyline points="{" ".join(f"{sx(i+1):.1f},{sy1(v):.1f}" for i,v in enumerate(TRAIN))}" fill="none" stroke="{faint}" stroke-width="1"/>')
    o.append(f'<polyline points="{" ".join(f"{sx(i+1):.1f},{sy1(v):.1f}" for i,v in enumerate(SM))}" fill="none" stroke="{acc}" stroke-width="2"/>')
    for s,v in VAL:
        o.append(f'<circle cx="{sx(s):.1f}" cy="{sy1(v):.1f}" r="3.2" fill="{surf}" stroke="{acc2}" stroke-width="1.8"/>')
    lx=L+330
    o.append(f'<line x1="{lx}" x2="{lx+26}" y1="{T+20}" y2="{T+20}" stroke="{faint}" stroke-width="2.5"/>')
    o.append(f'<text x="{lx+32}" y="{T+24}" fill="{ink}" font-size="13">training loss, each step</text>')
    o.append(f'<line x1="{lx}" x2="{lx+26}" y1="{T+42}" y2="{T+42}" stroke="{acc}" stroke-width="2.5"/>')
    o.append(f'<text x="{lx+32}" y="{T+46}" fill="{ink}" font-size="13">training loss, 25-step average</text>')
    o.append(f'<circle cx="{lx+13}" cy="{T+64}" r="4" fill="{surf}" stroke="{acc2}" stroke-width="2"/>')
    o.append(f'<text x="{lx+32}" y="{T+68}" fill="{ink}" font-size="13">validation loss, every 50 steps</text>')
    s,v=VAL[-1]
    o.append(f'<text x="{sx(s)-4:.1f}" y="{sy1(v)-14:.1f}" fill="{ink}" font-size="13" text-anchor="end">1.76B tokens: val {v:.2f}</text>')
    # panel 2
    o.append(f'<polyline clip-path="url(#c2)" points="{" ".join(f"{sx(i+1):.1f},{sl(lr_at(i)):.1f}" for i in range(0,STEPS,5))}" fill="none" stroke="{mut}" stroke-width="1.6" stroke-dasharray="4 4"/>')
    o.append(f'<polyline clip-path="url(#c2)" points="{" ".join(f"{sx(i+1):.1f},{sy2(v):.1f}" for i,v in enumerate(TRAIN))}" fill="none" stroke="{faint}" stroke-width="1"/>')
    o.append(f'<polyline clip-path="url(#c2)" points="{" ".join(f"{sx(i+1):.1f},{sy2(v):.1f}" for i,v in enumerate(SM))}" fill="none" stroke="{acc}" stroke-width="2"/>')
    for s,v in VAL:
        if v<=Z1: o.append(f'<circle cx="{sx(s):.1f}" cy="{sy2(v):.1f}" r="3.2" fill="{surf}" stroke="{acc2}" stroke-width="1.8"/>')
    o.append(f'<text x="{sx(2400):.1f}" y="{sl(lr_at(2400))-10:.1f}" fill="{mut}" font-size="13">learning rate (dashed, right axis)</text>')
    for s in (1000,2000,3360):
        v=dict(VAL)[s]; o.append(f'<text x="{sx(s)+(-8 if s==3360 else 0):.1f}" y="{sy2(v)-12:.1f}" fill="{ink}" font-size="13" font-weight="bold" text-anchor="{"end" if s==3360 else "middle"}">{v:.2f}</text>')
    # panel 3
    o.append(f'<line x1="{L}" x2="{W-R}" y1="{sy3(1):.1f}" y2="{sy3(1):.1f}" stroke="{ink}" stroke-width="1.5" stroke-dasharray="7 5"/>')
    o.append(f'<text x="{W-R-6}" y="{sy3(1)-7:.1f}" fill="{ink}" font-size="13" text-anchor="end">clipping threshold 1.0</text>')
    o.append(f'<polyline points="{" ".join(f"{sx(i+1):.1f},{sy3(min(max(g,0.15),12)):.1f}" for i,g in enumerate(GN))}" fill="none" stroke="{acc}" stroke-width="1.2"/>')
    o.append(f'<text x="{sx(495)+10:.1f}" y="{sy3(GN[494])+4:.1f}" fill="{ink}" font-size="13">largest after warm-up: {GN[207]:.2f} (step 207), {GN[494]:.2f} (step 494)</text>')
    o.append(f'<text x="{sx(1)+6:.1f}" y="{sy3(GN[0])+4:.1f}" fill="{ink}" font-size="13">step 0: {GN[0]:.1f}</text>')
    o.append('</svg>'); return '\n'.join(o)
light=('#0b1a33','#4a5b78','#dde5f2','#0b5fd6','#ffffff','#eb6834','#a9c3ee')
dark=('#e8eefc','#9fb0cf','#22355a','#38bdf8','#0b162d','#d95926','#2b5d86')
